    try {
      const response = await getAdminUsers();
      const data = Array.isArray(response.data) ? response.data : [];
      return data.length;
    } catch (error) {
      console.error('Error fetching users count:', error);
      return 0;
    }
  }, []);

  // Socket listener for new users
  useEffect(() => {
    if (!socket) {
      console.log('⚠️ Socket not connected');
      return;
